# Generated by Descant: acceptance tests.
# frozen_string_literal: true

require "rails_helper"

RSpec.describe "Timekeeping handoff round trip from the monolith store" do
  include_context "timekeeping entry writes without transactional fixtures"

  let(:round_trip_token) { "service-#{SecureRandom.hex(24)}" }

  around do |example|
    with_timekeeping_env(
      Timekeeping::Environment::TOKEN_PUBLIC_KEY => rsa_key_pair.public_key.to_pem,
      Timekeeping::Environment::SERVICE_TOKEN => round_trip_token
    ) { example.run }
  end

  before do
    Timekeeping::Admission.ensure_initial!
    Timekeeping::Admission.fence!
  end

  it "loads the monolith store's checkpoint file and exports its audits, receipts and operation receipts unchanged" do
    file = Rails.root.join("../spec/fixtures/files/timekeeping_handoff/monolith_checkpoint.json").read
    source = Timekeeping::Handoff::Checkpoint.from_json(file)
    %w[invoice_operations entry_audits idempotency_records].each do |table|
      expect(source.rows.fetch(table)).not_to be_empty, "the checkpoint file holds no #{table} rows"
    end

    put "/internal/v1/handoff/checkpoint", params: file,
                                           headers: { "Authorization" => "Bearer #{round_trip_token}",
                                                      "CONTENT_TYPE" => "application/json" }
    expect(response.status).to eq(200)

    get "/internal/v1/handoff/checkpoint", headers: { "Authorization" => "Bearer #{round_trip_token}" }
    expect(response.status).to eq(200)
    exported = Timekeeping::Handoff::Checkpoint.from_json(response.body)

    # "Populated audits, idempotency receipts and operation receipts round-trip between the two stores unchanged"
    expect(exported.digest).to eq(source.digest)
    Timekeeping::Handoff::Checkpoint::TABLES.each_key do |table|
      expect(exported.rows.fetch(table).map { |row| Timekeeping::Handoff::Checkpoint.encode_row(table, row) })
        .to match_array(source.rows.fetch(table).map { |row| Timekeeping::Handoff::Checkpoint.encode_row(table, row) })
    end
  end
end
